// Mesma lista dos fluxos de EAP/Apontamentos (consulta manual na tabela EAP).
const ids = [32, 51, 66, 73, 86, 87, 88, 89, 90, 94, 110, 114, 115, 121, 127];
return ids.map(id_eap => ({ json: { id_eap } }));

const corpo = $json.data ?? $json.body?.data ?? $json.body ?? $json;
const idEap = $('Loop id_eap (1 por vez)').item.json.id_eap;

// A resposta do endpoint ainda nao foi vista de perto: aceita os formatos mais
// provaveis e, se nenhum casar, o erro mostra as chaves reais que vieram.
const bruto = corpo.cards ?? corpo.cards_ativos ?? corpo.tarefas ?? (Array.isArray(corpo) ? corpo : null);
if (!Array.isArray(bruto)) throw new Error('Formato inesperado em cards_ativos/' + idEap + ' - chaves recebidas: ' + JSON.stringify(Object.keys(corpo || {})));

const vazio = v => v === null || v === undefined || (typeof v === 'string' && v.trim() === '');
const n = v => { if (vazio(v)) return null; const x = Number(typeof v === 'string' ? v.trim().replace(',', '.') : v); return Number.isFinite(x) ? x : null; };
const s = (v, max) => { if (vazio(v)) return null; const t = String(v).trim(); return t.length > max ? t.slice(0, max) : t; };
const d = v => { if (vazio(v)) return null; const t = String(v).trim().slice(0, 10); return /^\d{4}-\d{2}-\d{2}$/.test(t) ? t : null; };
const q = String.fromCharCode(96);
const escapar = (v) => "'" + String(v).replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\x00/g, '') + "'";
const sqlVal = (v) => (v === null || v === undefined) ? 'NULL' : (typeof v === 'number' ? String(v) : escapar(v));

// limites de texto = tamanho das colunas em painelmse.eap_cards_ativos
const rows = bruto.map(c => ({
  card_id: s(c.card_id ?? c.id_card ?? c.id, 30),
  id_eap_tabela: n(corpo.id_eap_tabela ?? corpo.id_eap ?? c.id_eap_tabela ?? idEap),
  nome_eap: s(corpo.nome_eap ?? c.nome_eap, 120),
  id_obra: n(corpo.id_obra ?? c.id_obra),
  nome_obra: s(corpo.nome_obra ?? c.nome_obra, 120),
  edt: s(c.edt, 60),
  tarefa: s(c.tarefa ?? c.tarefa_nome ?? c.nome_tarefa, 255),
  resp_planejamento: s(c.resp_planejamento ?? c.responsavel_planejamento ?? c.planejamento, 120),
  responsavel_encarregado: s(c.responsavel_encarregado ?? c.encarregado ?? c.encarregado_nome, 120),
  supervisor_coordenador: s(c.supervisor_coordenador ?? c.supervisor ?? c.coordenador, 120)
})).filter(r => r.card_id != null);

// --- MySQL: painelmse.eap_cards_ativos (PK = card_id) ---
const COLUNAS = ['card_id','id_eap_tabela','nome_eap','id_obra','nome_obra','edt','tarefa','resp_planejamento','responsavel_encarregado','supervisor_coordenador'];
const colsSql = COLUNAS.map(c => q + c + q).join(',');
const tuplas = rows.map(l => '(' + COLUNAS.map(c => sqlVal(l[c])).join(',') + ')').join(',\n');
const updSql = COLUNAS.filter(c => c !== 'card_id').map(c => q + c + q + ' = VALUES(' + q + c + q + ')').join(', ');
const sqlMySql = rows.length
  ? 'INSERT INTO eap_cards_ativos (' + colsSql + ') VALUES ' + tuplas + ' ON DUPLICATE KEY UPDATE ' + updSql + ', ' + q + 'sincronizado_em' + q + ' = CURRENT_TIMESTAMP'
  : 'SELECT 1';

// cards_ativos e retrato do AGORA: o que sumiu da resposta tem que sair da tabela.
// Roda antes ou depois do INSERT, tanto faz - a lista de quem fica e a mesma.
const idSql = sqlVal(n(idEap));
const listaSql = rows.map(r => sqlVal(r.card_id)).join(',');
const sqlDelete = rows.length
  ? 'DELETE FROM eap_cards_ativos WHERE id_eap_tabela = ' + idSql + ' AND card_id NOT IN (' + listaSql + ')'
  : 'DELETE FROM eap_cards_ativos WHERE id_eap_tabela = ' + idSql;

// mesma limpeza no Supabase, via PostgREST
const listaUrl = rows.map(r => '%22' + encodeURIComponent(String(r.card_id)) + '%22').join(',');
const urlDeleteSupabase = 'https://gebjlhkywtnpfqjrakok.supabase.co/rest/v1/cards_ativos?id_eap_tabela=eq.' + encodeURIComponent(String(n(idEap)))
  + (rows.length ? '&card_id=not.in.(' + listaUrl + ')' : '');

return [{ json: { rows, sqlMySql, sqlDelete, urlDeleteSupabase, total: rows.length } }];
